-- 0) Schema guard -------------------------------------------
-- Creates the tables only if they don't already exist yet, matching
-- src/lib/types.ts exactly. If your `zones` / `booths` / `booth_activities`
-- / `event_info` tables already exist with different column names, DELETE
-- this block and just make sure the column names below line up.
create table if not exists public.zones (
  zone_id      bigint generated always as identity primary key,
  zone_code    text unique not null,
  name_ar      text not null,
  name_en      text not null
);

create table if not exists public.booths (
  booth_number integer primary key,
  zone_id      bigint references public.zones (zone_id)
);

create table if not exists public.booth_activities (
  activity_id       bigint generated always as identity primary key,
  booth_number      integer not null references public.booths (booth_number),
  institution_ar    text,
  institution_en    text,
  activity_type_ar  text,
  activity_type_en  text check (activity_type_en in ('Workshop','Presentation','Storytelling')),
  activity_dates    text,
  description_ar    text,
  description_en    text
);

create table if not exists public.event_info (
  info_key   text primary key,
  value_ar   text,
  value_en   text
);

