-- 5) Floor-plan correction -------------------------------------
-- The physical floor plan changed after this file was first written:
-- booth 13 moved from "بوابة الكون" into "مرصد السماء", and booths 11 & 12
-- no longer exist anywhere in the venue (no space for them in the new
-- layout). This block runs AFTER the inserts above on purpose, so it always
-- wins and leaves the data in the correct final state no matter how many
-- times this file is re-run.
update public.booths
set zone_id = (select zone_id from public.zones where zone_code = 'sky_observatory')
where booth_number = 13;

delete from public.booth_activities where booth_number in (11, 12);
delete from public.booths where booth_number in (11, 12);

